//! Spike for trail 369: the request sequence of one recorded caliper answer, replayed against tsrs in-process
//! (`tsrs_api::Session::handle_request`) and over the `tsrs --api --async` pipe, timed the same way.
//!
//!   spike prepare <proxy-log> <replay.json>
//!   spike inproc  <replay.json>                 one fresh session in this process
//!   spike pipe    <tsrs-binary> <replay.json>   one fresh `tsrs --api --async` child
//!   spike cycles  <replay.json> <n>             n sessions in turn, each dropped: resident memory after each
//!   spike deep    <depth> <stack-mib> <file>    a type nested `depth` deep, checked in-process on a thread of that stack
use std::io::{BufRead, BufReader, Read, Write};
use std::process::{Command, Stdio};
use std::sync::Arc;
use std::time::Instant;

use serde_json::{Value, json};
use tsrs_api::{Handler, Response, Session, SessionOptions};
use tsrs_vfs::{FS, bundled, osvfs};

thread_local! {
    static PROJECTS: std::cell::RefCell<std::collections::HashMap<String, String>> = Default::default();
}

#[global_allocator]
static GLOBAL: mimalloc::MiMalloc = mimalloc::MiMalloc;

struct Call {
    method: String,
    params: Value,
    params_text: String,
    body: String,
    result: Option<Value>,
    error: Option<Value>,
}

fn load(path: &str) -> (String, Vec<Call>) {
    let replay: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let cwd = replay["cwd"].as_str().unwrap().to_string();
    let calls = replay["calls"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| Call {
            method: c["method"].as_str().unwrap().to_string(),
            params: c["params"].clone(),
            params_text: serde_json::to_string(&c["params"]).unwrap(),
            body: c["body"].as_str().unwrap().to_string(),
            result: c.get("result").cloned(),
            error: c.get("error").cloned(),
        })
        .collect();
    (cwd, calls)
}

fn rusage(who: i32) -> (f64, f64, i64) {
    let mut usage: libc::rusage = unsafe { std::mem::zeroed() };
    unsafe { libc::getrusage(who, &mut usage) };
    let ms = |t: libc::timeval| t.tv_sec as f64 * 1000.0 + t.tv_usec as f64 / 1000.0;
    (ms(usage.ru_utime), ms(usage.ru_stime), usage.ru_maxrss)
}

fn rss_mib() -> f64 {
    let out = Command::new("ps").args(["-o", "rss=", "-p", &std::process::id().to_string()]).output().unwrap();
    String::from_utf8_lossy(&out.stdout).trim().parse::<f64>().unwrap() / 1024.0
}

fn prepare(log: &str, out: &str) {
    let text = std::fs::read_to_string(log).unwrap();
    let mut cwd = String::new();
    let mut sent: Vec<(u64, Value, String)> = Vec::new();
    let mut answers = std::collections::HashMap::new();
    for line in text.lines() {
        let mut parts = line.splitn(3, ' ');
        let (dir, _t, body) = (parts.next().unwrap(), parts.next().unwrap(), parts.next().unwrap_or(""));
        match dir {
            "ARGS" => {
                let args: Vec<String> = serde_json::from_str(body).unwrap();
                let at = args.iter().position(|a| a == "--cwd").unwrap();
                cwd = args[at + 1].clone();
            }
            "C2S" => {
                let message: Value = serde_json::from_str(body).unwrap();
                if let Some(id) = message["id"].as_u64() {
                    sent.push((id, message, body.to_string()));
                }
            }
            "S2C" => {
                let message: Value = serde_json::from_str(body).unwrap();
                if let Some(id) = message["id"].as_u64() {
                    answers.insert(id, message);
                }
            }
            _ => {}
        }
    }
    let calls: Vec<Value> = sent
        .into_iter()
        .map(|(id, message, body)| {
            let answer = answers.get(&id).cloned().unwrap_or(Value::Null);
            let mut call = json!({ "method": message["method"], "params": message["params"], "body": body });
            if let Some(result) = answer.get("result") {
                call["result"] = result.clone();
            }
            if let Some(error) = answer.get("error") {
                call["error"] = error.clone();
            }
            call
        })
        .collect();
    let mut methods = std::collections::BTreeMap::<String, u64>::new();
    for call in &calls {
        *methods.entry(call["method"].as_str().unwrap().to_string()).or_default() += 1;
        if call["method"] == "batchRequests" {
            for request in call["params"]["requests"].as_array().unwrap() {
                *methods.entry(format!("  in batch: {}", request["method"].as_str().unwrap())).or_default() += 1;
            }
        }
    }
    eprintln!("{} requests: {methods:#?}", calls.len());
    std::fs::write(out, serde_json::to_string(&json!({ "cwd": cwd, "calls": calls })).unwrap()).unwrap();
}

fn new_session(cwd: &str) -> Arc<Session> {
    let fs: Arc<dyn FS> = Arc::new(bundled::wrap_fs(osvfs::fs()));
    Session::new(SessionOptions::new(cwd.to_string(), bundled::default_lib_path(), fs, false))
}

/// Answers compared with the recorded ones, skipping the snapshot handles a fresh numbering may change.
fn compare(calls: &[Call], answers: &[Result<String, String>]) -> (usize, Vec<String>) {
    let mut differ = 0;
    let mut first = Vec::new();
    for (call, answer) in calls.iter().zip(answers) {
        let same = match answer {
            Ok(text) => {
                let value: Value = serde_json::from_str(text).unwrap_or(Value::Null);
                call.error.is_none()
                    && (matches!(call.method.as_str(), "createSnapshot" | "updateSnapshot")
                        || Some(&value) == call.result.as_ref())
            }
            Err(_) => call.error.is_some(),
        };
        if !same {
            differ += 1;
            if std::env::var("DIFF").is_ok() {
                eprintln!(
                    "DIFF {} {}\n  recorded {}\n  actual   {:?}",
                    call.method,
                    call.params_text,
                    serde_json::to_string(&call.result).unwrap().chars().take(400).collect::<String>(),
                    answer.as_ref().map(|t| t.chars().take(400).collect::<String>())
                );
            }
            if first.len() < 5 {
                first.push(format!("{} {}", call.method, call.params_text.chars().take(160).collect::<String>()));
            }
        }
    }
    (differ, first)
}

struct Timing {
    setup_ms: f64,
    snapshot_ms: f64,
    queries_ms: f64,
    queries: usize,
}

fn segments(calls: &[Call], stamps: &[f64]) -> Timing {
    // stamps[i] is the time at which answer i arrived, stamps[0] the start; the first createSnapshot splits setup.
    let snap = calls.iter().position(|c| c.method == "createSnapshot").unwrap();
    Timing {
        setup_ms: stamps[snap],
        snapshot_ms: stamps[snap + 1] - stamps[snap],
        queries_ms: stamps[calls.len()] - stamps[snap + 1],
        queries: calls.len() - snap - 1,
    }
}

fn replay_inproc(session: &Session, calls: &[Call], remap: bool) -> (Vec<Result<String, String>>, Vec<f64>) {
    let mut snapshots = std::collections::HashMap::<u64, u64>::new();
    let mut answers = Vec::with_capacity(calls.len());
    let mut stamps = Vec::with_capacity(calls.len() + 1);
    let start = Instant::now();
    stamps.push(0.0);
    for call in calls {
        let params = if remap && !snapshots.is_empty() {
            let mut params = call.params.clone();
            remap_snapshots(&mut params, &snapshots);
            serde_json::to_string(&params).unwrap()
        } else {
            call.params_text.clone()
        };
        let answer = match session.handle_request(&call.method, params.as_bytes()) {
            Ok(Response::Json(text)) => Ok(text),
            Ok(Response::Binary(_)) => Err("binary".to_string()),
            Err(error) => Err(error.to_string()),
        };
        if remap && matches!(call.method.as_str(), "createSnapshot" | "updateSnapshot") {
            if let (Ok(text), Some(recorded)) = (&answer, call.result.as_ref()) {
                let actual: Value = serde_json::from_str(text).unwrap();
                snapshots.insert(recorded["snapshot"].as_u64().unwrap(), actual["snapshot"].as_u64().unwrap());
                if let (Some(from), Some(to)) =
                    (recorded["projects"][0]["id"].as_str(), actual["projects"][0]["id"].as_str())
                {
                    PROJECTS.with(|p| p.borrow_mut().insert(from.to_string(), to.to_string()));
                }
            }
        }
        answers.push(answer);
        stamps.push(start.elapsed().as_secs_f64() * 1000.0);
    }
    (answers, stamps)
}

fn remap_snapshots(value: &mut Value, map: &std::collections::HashMap<u64, u64>) {
    match value {
        Value::Object(object) => {
            for (key, inner) in object.iter_mut() {
                if key == "snapshot" {
                    if let Some(to) = inner.as_u64().and_then(|from| map.get(&from)) {
                        *inner = json!(to);
                    }
                } else if key == "project" && inner.is_string() {
                    if let Some(to) = PROJECTS.with(|p| p.borrow().get(inner.as_str().unwrap()).cloned()) {
                        *inner = json!(to);
                    }
                } else {
                    remap_snapshots(inner, map);
                }
            }
        }
        Value::Array(items) => items.iter_mut().for_each(|item| remap_snapshots(item, map)),
        _ => {}
    }
}

fn on_big_stack<T: Send + 'static>(mib: usize, f: impl FnOnce() -> T + Send + 'static) -> T {
    std::thread::Builder::new().stack_size(mib << 20).spawn(f).unwrap().join().unwrap()
}

fn inproc(path: &str) {
    let (cwd, calls) = load(path);
    let (u0, s0, _) = rusage(libc::RUSAGE_SELF);
    let wall = Instant::now();
    let (answers, stamps, session_ms) = on_big_stack(512, move || {
        let began = Instant::now();
        let session = new_session(&cwd);
        let session_ms = began.elapsed().as_secs_f64() * 1000.0;
        let (answers, stamps) = replay_inproc(&session, &calls, false);
        session.close();
        (answers, stamps, session_ms)
    });
    let wall_ms = wall.elapsed().as_secs_f64() * 1000.0;
    let (u1, s1, maxrss) = rusage(libc::RUSAGE_SELF);
    let (_, calls) = load(path);
    let t = segments(&calls, &stamps);
    let (differ, first) = compare(&calls, &answers);
    println!(
        "{}",
        json!({ "mode": "inproc", "requests": calls.len(), "sessionMs": session_ms, "setupMs": t.setup_ms,
            "snapshotMs": t.snapshot_ms, "queriesMs": t.queries_ms, "queries": t.queries,
            "answerMs": t.snapshot_ms + t.queries_ms, "wallMs": wall_ms, "cpuMs": (u1 - u0) + (s1 - s0),
            "peakRssMiB": maxrss as f64 / 1048576.0, "differ": differ, "firstDiffer": first })
    );
}

fn read_frame(reader: &mut impl BufRead) -> Option<Vec<u8>> {
    let mut length = None;
    loop {
        let mut line = String::new();
        if reader.read_line(&mut line).ok()? == 0 {
            return None;
        }
        let line = line.trim_end();
        if line.is_empty() {
            break;
        }
        if let Some(value) = line.strip_prefix("Content-Length:") {
            length = value.trim().parse::<usize>().ok();
        }
    }
    let mut body = vec![0; length?];
    reader.read_exact(&mut body).ok()?;
    Some(body)
}

fn pipe(binary: &str, path: &str) {
    let (cwd, calls) = load(path);
    let wall = Instant::now();
    let mut child = Command::new(binary)
        .args(["--api", "--async", "--cwd", &cwd])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    let mut input = child.stdin.take().unwrap();
    let mut output = BufReader::new(child.stdout.take().unwrap());
    let mut answers = Vec::with_capacity(calls.len());
    let mut stamps = Vec::with_capacity(calls.len() + 1);
    let start = Instant::now();
    stamps.push(0.0);
    for call in &calls {
        write!(input, "Content-Length: {}\r\n\r\n", call.body.len()).unwrap();
        input.write_all(call.body.as_bytes()).unwrap();
        input.flush().unwrap();
        let id = serde_json::from_str::<Value>(&call.body).unwrap()["id"].clone();
        loop {
            let frame = read_frame(&mut output).unwrap();
            let message: Value = serde_json::from_slice(&frame).unwrap();
            if message.get("id") == Some(&id) {
                answers.push(match message.get("error") {
                    Some(error) => Err(error.to_string()),
                    None => Ok(message["result"].to_string()),
                });
                break;
            }
        }
        stamps.push(start.elapsed().as_secs_f64() * 1000.0);
    }
    drop(input);
    child.wait().unwrap();
    let wall_ms = wall.elapsed().as_secs_f64() * 1000.0;
    let (u, s, maxrss) = rusage(libc::RUSAGE_CHILDREN);
    let (us, ss, _) = rusage(libc::RUSAGE_SELF);
    let t = segments(&calls, &stamps);
    let (differ, first) = compare(&calls, &answers);
    println!(
        "{}",
        json!({ "mode": "pipe", "binary": binary, "requests": calls.len(), "setupMs": t.setup_ms,
            "snapshotMs": t.snapshot_ms, "queriesMs": t.queries_ms, "queries": t.queries,
            "answerMs": t.snapshot_ms + t.queries_ms, "wallMs": wall_ms, "childCpuMs": u + s, "clientCpuMs": us + ss,
            "childPeakRssMiB": maxrss as f64 / 1048576.0, "differ": differ, "firstDiffer": first })
    );
}

/// `n` sessions in turn, each answering the recording and then closed and dropped (`fresh`), or one session answering
/// it `n` times, releasing its snapshot after each (`one`). Resident memory after each, the recording held throughout.
fn cycles(path: &str, n: usize, one: bool) {
    let (cwd, calls) = load(path);
    let calls = Arc::new(calls);
    println!("{}", json!({ "cycle": 0, "rssMiB": rss_mib() }));
    let shared = new_session(&cwd);
    if std::env::var("SAME_THREAD").is_ok() {
        // Every cycle on one long-lived checker thread, as an embedder would run it.
        let (tx, rx) = std::sync::mpsc::channel::<Box<dyn FnOnce() + Send>>();
        let worker = std::thread::Builder::new()
            .stack_size(512 << 20)
            .spawn(move || {
                for job in rx {
                    job();
                }
            })
            .unwrap();
        for cycle in 1..=n {
            let (cwd, calls, shared) = (cwd.clone(), Arc::clone(&calls), Arc::clone(&shared));
            let (done_tx, done_rx) = std::sync::mpsc::channel();
            tx.send(Box::new(move || {
                done_tx.send(one_cycle(&cwd, &calls, &shared, one)).unwrap();
            }))
            .unwrap();
            let (differ, ms, peak) = done_rx.recv().unwrap();
            println!(
                "{}",
                json!({ "cycle": cycle, "rssAfterAnswerMiB": peak, "rssAfterDropMiB": rss_mib(), "failed": differ, "ms": ms })
            );
        }
        drop(tx);
        worker.join().unwrap();
        return;
    }
    for cycle in 1..=n {
        let (cwd, calls, shared) = (cwd.clone(), Arc::clone(&calls), Arc::clone(&shared));
        let (differ, ms, peak) = on_big_stack(512, move || one_cycle(&cwd, &calls, &shared, one));
        println!(
            "{}",
            json!({ "cycle": cycle, "rssAfterAnswerMiB": peak, "rssAfterDropMiB": rss_mib(), "failed": differ, "ms": ms })
        );
    }
}

fn one_cycle(cwd: &str, calls: &[Call], shared: &Arc<Session>, one: bool) -> (usize, f64, f64) {
    {
        {
            let began = Instant::now();
            let session = if one { Arc::clone(shared) } else { new_session(cwd) };
            // Handles (node, symbol and type ids) are numbered per process, so a later session cannot replay the
            // recording past the snapshot: it builds the same program and has the checker check the component's file.
            let snap = calls.iter().position(|c| c.method == "createSnapshot").unwrap();
            PROJECTS.with(|p| p.borrow_mut().clear());
            let (mut answers, _) = replay_inproc(&session, &calls[..=snap], true);
            let created: Value = serde_json::from_str(answers[snap].as_ref().unwrap()).unwrap();
            let root = calls[snap].params["createPrograms"][0]["rootFiles"][0].clone();
            let params = json!({ "snapshot": created["snapshot"], "project": created["projects"][0]["id"], "file": root });
            let diagnostics = session.handle_request("getSemanticDiagnostics", params.to_string().as_bytes());
            answers.push(match diagnostics {
                Ok(Response::Json(text)) => Ok(text),
                other => Err(format!("{other:?}")),
            });
            let peak = rss_mib();
            let snapshots: Vec<u64> = calls
                .iter()
                .zip(&answers)
                .filter(|(c, _)| matches!(c.method.as_str(), "createSnapshot" | "updateSnapshot"))
                .filter_map(|(_, a)| a.as_ref().ok())
                .filter_map(|text| serde_json::from_str::<Value>(text).ok()?["snapshot"].as_u64())
                .collect();
            if one {
                for snapshot in snapshots {
                    drop(session.handle_request("release", json!({ "snapshot": snapshot }).to_string().as_bytes()));
                }
            } else {
                session.close();
            }
            drop(session);
            if std::env::var("COLLECT").is_ok() {
                // Ask mimalloc to return what it holds free, to tell allocator retention from memory still in use.
                unsafe { libmimalloc_sys::mi_collect(true) };
            }
            let ms = began.elapsed().as_secs_f64() * 1000.0;
            let failed = answers.iter().filter(|a| a.is_err()).count();
            (failed, ms, peak)
        }
    }
}

/// A file whose type nests `depth` levels (`{ a: { a: ... string ... } }`), checked through createSnapshot with an
/// in-memory layer and getSemanticDiagnostics, on a thread with `stack_mib` of stack.
fn deep(depth: usize, stack_mib: usize, file: &str) {
    let mut text = String::from("export type Deep = ");
    for _ in 0..depth {
        text.push_str("{ a: ");
    }
    text.push_str("string");
    for _ in 0..depth {
        text.push_str(" }");
    }
    text.push_str(";\nexport const value: Deep = null as any;\nexport const s: string = value");
    for _ in 0..depth {
        text.push_str(".a");
    }
    text.push_str(";\n");
    let file = file.to_string();
    let outcome = on_big_stack(stack_mib, move || {
        let session = new_session("/");
        let options = json!({ "strict": true, "noEmit": true, "target": 9, "module": 99, "moduleResolution": 100 });
        let params = json!({
            "fileSystem": { "kind": "layer", "files": { file.clone(): text } },
            "createPrograms": [{ "rootFiles": [file.clone()], "compilerOptions": options }],
        });
        let began = Instant::now();
        let created = session.handle_request("createSnapshot", params.to_string().as_bytes());
        let Ok(Response::Json(created)) = created else { return format!("createSnapshot failed: {created:?}") };
        let created: Value = serde_json::from_str(&created).unwrap();
        let params = json!({ "snapshot": created["snapshot"], "project": created["projects"][0]["id"], "file": file });
        let diagnostics = session.handle_request("getSemanticDiagnostics", params.to_string().as_bytes());
        let summary = match diagnostics {
            Ok(Response::Json(text)) => format!("ok, {} bytes of diagnostics", text.len()),
            other => format!("{other:?}").chars().take(300).collect(),
        };
        // The query path, on this thread: the module's exports, `Deep`'s declared type, printed without truncation.
        let call = |method: &str, extra: Value| {
            let mut params = json!({ "snapshot": created["snapshot"], "project": created["projects"][0]["id"] });
            params.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
            match session.handle_request(method, params.to_string().as_bytes()) {
                Ok(Response::Json(text)) => Ok(serde_json::from_str::<Value>(&text).unwrap()),
                other => Err(format!("{method}: {other:?}").chars().take(300).collect::<String>()),
            }
        };
        let printed = (|| {
            let module = call("getSymbolOfSourceFile", json!({ "file": file }))?;
            let exports = call("getExportsOfModule", json!({ "symbol": module["reference"] }))?;
            let deep = exports.as_array().unwrap().iter().find(|e| e["name"] == "Deep").unwrap().clone();
            let declared = call("getDeclaredTypeOfSymbol", json!({ "symbol": deep["reference"] }))?;
            let text = call("typeToString", json!({ "type": declared["id"], "flags": 1 | 16384 | 1_048_576 | 8_388_608 }))?;
            Ok::<usize, String>(text.as_str().map_or(0, str::len))
        })();
        format!("{summary}; typeToString {printed:?} in {:?}", began.elapsed())
    });
    println!("{}", json!({ "mode": "deep", "depth": depth, "stackMiB": stack_mib, "outcome": outcome }));
}

/// A program whose `moduleResolution` names no kind reaches the resolver's panic (as in pinned Go, which crashes):
/// does the session turn it into an error and stay usable?
fn panic_probe() {
    let outcome = on_big_stack(512, || {
        let session = new_session("/");
        let file = "/virtual/panic.ts";
        let make = |resolution: u32| {
            json!({
                "fileSystem": { "kind": "layer", "files": { file: "import x from \"./other\";\nexport const z = x;\n" } },
                "createPrograms": [{ "rootFiles": [file], "compilerOptions": { "moduleResolution": resolution, "noEmit": true } }],
            })
            .to_string()
        };
        let bad = session.handle_request("createSnapshot", make(12345).as_bytes());
        let good = session.handle_request("createSnapshot", make(100).as_bytes());
        format!("bad: {bad:?}; then good: {}", format!("{good:?}").chars().take(120).collect::<String>())
    });
    println!("{}", json!({ "mode": "panic", "outcome": outcome }));
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    match args.get(1).map(String::as_str) {
        Some("prepare") => prepare(&args[2], &args[3]),
        Some("inproc") => inproc(&args[2]),
        Some("pipe") => pipe(&args[2], &args[3]),
        Some("cycles") => cycles(&args[2], args[3].parse().unwrap(), false),
        Some("onesession") => cycles(&args[2], args[3].parse().unwrap(), true),
        Some("panic") => panic_probe(),
        Some("deep") => deep(args[2].parse().unwrap(), args[3].parse().unwrap(), &args[4]),
        _ => eprintln!("usage: spike prepare|inproc|pipe|cycles|deep ..."),
    }
}
#!/usr/bin/env bash
# A type nested <depth> deep, checked and printed in-process on a thread with <stack> MiB, each in its own process;
# the exit status shows whether a stack overflow took the process down. usage: deep.sh
set -uo pipefail
dir="$HOME/Projects/caliper-fixtures/tsrs-crates"
bash "$dir/c.sh" "$dir/spike" cargo build --release 2>&1 | tail -1
for stack in 2 8 512; do
  for depth in 500 2000 10000; do
    "$dir/spike/target/release/spike" deep "$depth" "$stack" /virtual/deep.ts > "$dir/deep-$stack-$depth.out" 2> "$dir/deep-$stack-$depth.err"
    status=$?
    echo "stack ${stack}MiB depth $depth exit $status out: $(head -c 300 "$dir/deep-$stack-$depth.out") stderr: $(head -c 200 "$dir/deep-$stack-$depth.err" | tr '\n' ' ')"
  done
done
#!/usr/bin/env bash
# Memory across sessions and snapshots in-process, all on one long-lived checker thread, with mimalloc asked to give
# back free memory after each drop. usage: memory.sh [n]
