402	    }
403	}
404	
405	/// Resolves the request's components with the checker. Blocks; builds its own single-threaded runtime, so it must
406	/// not be called from inside one.
407	pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
408	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
409	        Ok(runtime) => runtime,
410	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
411	    };
412	    runtime.block_on(run(request))
413	}
414	
415	/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
416	/// the checker cannot be asked about.
417	fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
418	    let mut outcome = SemanticOutcome::default();
419	    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
420	    let mut order: Vec<&Utf8Path> = Vec::new();
421	    for target in &request.targets {
422	        if target.exports.is_empty() {
423	            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
424	            continue;
425	        }
426	        let group = by_file.entry(target.file_path.as_path()).or_default();
427	        if group.is_empty() {
428	            order.push(target.file_path.as_path());
429	        }
430	        group.push(target);
431	    }
432	    (outcome, by_file, order)
433	}
434	
435	fn supervisor_config(request: &SemanticRequest) -> Result<SupervisorConfig, String> {
436	    let tsc_path = locate::find_tsc(&request.project_root, request.tsc_path.as_deref())?;
437	    let mut config = SupervisorConfig::new(tsc_path, request.project_root.clone(), request.expected_versions);
438	    config.handshake_timeout = request.request_timeout;
439	    config.extra_env.clone_from(&request.extra_env);
440	    Ok(config)
441	}
442	
443	async fn run(request: SemanticRequest) -> SemanticOutcome {
444	    if request.targets.iter().all(|target| target.exports.is_empty()) {
445	        return group_by_file(&request).0;
446	    }
447	    let config = match supervisor_config(&request) {
448	        Ok(config) => config,
449	        Err(reason) => return SemanticOutcome::unavailable(reason),
450	    };
451	    let supervisor = match Supervisor::spawn(config).await {
452	        Ok(supervisor) => supervisor,
453	        Err(error) => return SemanticOutcome::unavailable(error.to_string()),
454	    };
455	    let outcome = answer_with(&supervisor, &request).await;
456	    supervisor.shutdown().await.ok();
457	    outcome
458	}
459	
460	/// The files of the request's exported targets, in first-seen order: the roots of the program that answers it.
461	fn root_files(request: &SemanticRequest) -> Vec<String> {
462	    group_by_file(request).2.iter().map(|file| file.to_string()).collect()
463	}
464	
465	/// Answers the request's targets with a checker that is already running: one program rooted at their files, released
466	/// once they are answered.
467	async fn answer_with(supervisor: &Supervisor, request: &SemanticRequest) -> SemanticOutcome {
468	    let files = root_files(request);
469	    if files.is_empty() {
470	        return group_by_file(request).0;
471	    }
472	    let started = std::time::Instant::now();
473	    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
474	    let opened =
475	        Rpc::open(supervisor.client(), request.request_timeout, tsconfig, &files, request.record_to.is_some()).await;
476	    let rpc = match opened {
477	        Ok(rpc) => Arc::new(rpc),
478	        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
479	    };
480	    tracing::debug!(program_ms = started.elapsed().as_millis() as u64, "semantic program built");
481	    let answered = answer_on(&rpc, request, &files).await;
482	    rpc.release().await;
483	    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
484	}
485	
486	/// Answers the request's targets on a snapshot whose program is rooted at `files` ([`root_files`]). The snapshot is
487	/// left as it is, for the caller to keep or release.
488	async fn answer_on(rpc: &Arc<Rpc>, request: &SemanticRequest, files: &[String]) -> Result<SemanticOutcome, CallError> {
489	    let (mut outcome, by_file, order) = group_by_file(request);
490	    let mut answered = session(rpc, request, files, &by_file, &order).await?;
491	    outcome.components.append(&mut answered.components);
492	    outcome.fallbacks.append(&mut answered.fallbacks);
493	    Ok(outcome)
494	}
495	
496	async fn session(
497	    rpc: &Arc<Rpc>,
498	    request: &SemanticRequest,
499	    files: &[String],
500	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
501	    order: &[&Utf8Path],
502	) -> Result<SemanticOutcome, CallError> {
503	    let started = std::time::Instant::now();
504	    let converter = Converter::new(rpc.clone(), request.reverse_queries);
505	    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
506	    let interner = Arc::new(PropInterner::default());
507	
508	    let mut tasks = JoinSet::new();
509	    for file in order {
510	        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
511	        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
512	        tasks.spawn(async move {
513	            let _permit = limit.acquire().await;
514	            answer_file(&rpc, &converter, &interner, targets).await
515	        });
516	    }
517	
518	    let mut outcome = SemanticOutcome::default();
519	    let mut generic = Vec::new();
520	    let mut failure = None;
521	    while let Some(joined) = tasks.join_next().await {
522	        match joined {
523	            Ok(Ok((mut answered, mut instantiations))) => {
524	                outcome.components.append(&mut answered.components);
525	                outcome.fallbacks.append(&mut answered.fallbacks);
526	                generic.append(&mut instantiations);
527	            }
528	            Ok(Err(error)) => {
529	                failure = Some(error);
530	                tasks.abort_all();
531	            }
532	            // A panic inside a worker must not silently leave its components structural.
533	            Err(joined) if joined.is_panic() => {
534	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
535	                tasks.abort_all();
536	            }
537	            // A cancelled task is one this loop aborted after a failure.
538	            Err(_cancelled) => {}
539	        }
540	    }
541	    if let Some(error) = failure {
542	        return Err(error);
543	    }
544	    if !generic.is_empty() {
545	        let mut instantiated =
546	            instantiate::answer(rpc, files, &request.project_root, &interner, request.reverse_queries, generic).await?;
547	        outcome.components.append(&mut instantiated.components);
548	        outcome.fallbacks.append(&mut instantiated.fallbacks);
549	    }
550	
551	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
552	        && let Ok(json) = serde_json::to_string_pretty(&recording)
553	        && let Err(error) = std::fs::write(path, json)
554	    {
555	        tracing::warn!("could not write the recording to {path}: {error}");
556	    }
557	    tracing::debug!(
558	        requests = ?rpc.calls(),
559	        files = files.len(),
560	        type_memo = ?converter.memo_stats(),
561	        total_ms = started.elapsed().as_millis() as u64,
562	        "semantic backend finished"
563	    );
564	    outcome.components.sort_by(|a, b| a.key.cmp(&b.key));
565	    outcome.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
566	    Ok(outcome)
567	}
568	
569	fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
570	    SemanticFallback { key: target.key.clone(), reason: reason.to_string() }
571	}
572	
573	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
574	/// generic components come back apart, to be answered from their instantiations once every file is done.
575	async fn answer_file(
576	    rpc: &Rpc,
577	    converter: &Converter,
578	    interner: &PropInterner,
579	    targets: Vec<Target>,
580	) -> Result<(SemanticOutcome, Vec<(Target, Instantiation)>), CallError> {
581	    let mut outcome = SemanticOutcome::default();
582	    let mut generic = Vec::new();
583	    let Some(first) = targets.first() else { return Ok((outcome, generic)) };
584	    let module = match module_exports(rpc, first.file_path.as_str()).await {
585	        Ok(Some(module)) => module,
586	        Ok(None) | Err(CallError::Rejected(_)) => {
587	            outcome
588	                .fallbacks
589	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
590	            return Ok((outcome, generic));
591	        }
592	        Err(fatal) => return Err(fatal),
593	    };
594	
595	    for target in &targets {
596	        let requests = Arc::new(AtomicU64::new(0));
597	        let started = std::time::Instant::now();
598	        let answered =
599	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &module, target)).await;
600	        tracing::debug!(
601	            component = %target.display_name,
602	            requests = requests.load(Ordering::Relaxed),
603	            ms = started.elapsed().as_millis() as u64,
604	            "semantic component answered"
605	        );
606	        match answered {
607	            Ok(Answer::Props(component::Props { props, composes })) => {
608	                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes });
609	            }
610	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
611	            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
612	            Err(CallError::Rejected(message)) => {
613	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
614	            }
615	            Err(fatal) => return Err(fatal),
616	        }
617	    }
618	    Ok((outcome, generic))
619	}
620	
621	/// The module `file` is, as the checker reads it, with its exports; `None` when the file is not in its program.
622	async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<component::Module>, CallError> {
623	    let Some(symbol) = rpc.source_file_symbol(file).await? else { return Ok(None) };
624	    let exports = rpc.exports_of_module(&symbol.reference).await?;
625	    Ok(Some(component::Module { symbol, exports }))
626	}
627	//! Finding the checker binary the project installed.
628	
629	use camino::{Utf8Path, Utf8PathBuf};
630	
631	/// The binaries searched for in each `node_modules`, in order of precedence: `typescript@7.1`'s `tsc`, then the `tsrs`
632	/// Node shim. An install that has both keeps using `typescript`, as before `tsrs` was supported; `--tsc-path` picks
633	/// the other.
634	const CANDIDATES: [[&str; 3]; 2] = [["typescript", "bin", "tsc"], ["tsrs", "bin", "tsrs"]];
635	
636	/// `explicit` if given (it must exist), else the binary of the nearest `node_modules` at or above `project_root` that
637	/// holds one: `typescript/bin/tsc`, else `tsrs/bin/tsrs`. The version is checked later, when the process is spawned.
638	pub(crate) fn find_tsc(project_root: &Utf8Path, explicit: Option<&Utf8Path>) -> Result<Utf8PathBuf, String> {
639	    if let Some(path) = explicit {
640	        return if path.is_file() { Ok(path.to_owned()) } else { Err(format!("no tsc binary at {path}")) };
641	    }
642	    project_root
643	        .ancestors()
644	        .flat_map(|dir| {
645	            CANDIDATES.map(|parts| parts.iter().fold(dir.join("node_modules"), |path, part| path.join(part)))
646	        })
647	        .find(|candidate| candidate.is_file())
648	        .ok_or_else(|| {
649	            format!(
650	                "no node_modules/typescript/bin/tsc or node_modules/tsrs/bin/tsrs at or above {project_root}; install \
651	                 `typescript@beta` (7.1) or `tsrs`, or pass --tsc-path"
652	            )
653	        })
654	}
655	
