661	    fn the_nearest_installed_typescript_above_the_project_wins() {
662	        let dir = tempfile::tempdir().unwrap();
663	        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
664	        let bin = root.join("node_modules/typescript/bin");
