53	/// Programs one `tsc` process builds before it is replaced. Its memory grows with every program it has loaded
54	/// (measured: antd reached 600 MiB after 50 single-component programs), and a fresh process costs 30 to 70 ms.
55	const MAX_REQUESTS_PER_PROCESS: u32 = 64;
