57	/// Resident memory, in MiB, past which a `tsc` process is replaced between requests. Measured single-component programs
58	/// peak at 157 to 612 MiB (antd the highest); a process past this has loaded more than a story session needs.
59	const DEFAULT_MAX_RSS_MIB: u64 = 768;
