108	/// The resident memory of a process in MiB: `/proc` where it exists, else `ps`. `None` when neither answers.
109	fn resident_mib(pid: u32) -> Option<u64> {
110	    let kib = match std::fs::read_to_string(format!("/proc/{pid}/status")) {
111	        Ok(status) => status
112	            .lines()
113	            .find_map(|line| line.strip_prefix("VmRSS:"))?
114	            .split_whitespace()
115	            .next()?
116	            .parse::<u64>()
117	            .ok()?,
118	        Err(_) => {
119	            let output = std::process::Command::new("ps").args(["-o", "rss=", "-p", &pid.to_string()]).output().ok()?;
120	            String::from_utf8_lossy(&output.stdout).trim().parse::<u64>().ok()?
121	        }
122	    };
123	    Some(kib / 1024)
124	}
