171	/// The requests waiting for the checker, in two queues by priority, first in first out within each. A request is
172	/// filed by its priority when it arrives and moved to the interactive queue when a caller raised it while it waited.
173	/// After [`INTERACTIVE_STREAK`] interactive requests in a row while the background queue is not empty, the next is
174	/// the oldest background request.
175	struct Queue<T> {
176	    interactive: VecDeque<(T, SharedPriority)>,
177	    background: VecDeque<(T, SharedPriority)>,
178	    /// Interactive requests taken in a row while a background one waited.
179	    streak: u32,
180	}
181	
182	impl<T> Default for Queue<T> {
183	    fn default() -> Self {
184	        Self { interactive: VecDeque::new(), background: VecDeque::new(), streak: 0 }
185	    }
186	}
187	
188	impl<T> Queue<T> {
189	    fn push(&mut self, item: T, priority: SharedPriority) {
190	        match priority.get() {
191	            Priority::Interactive => self.interactive.push_back((item, priority)),
192	            Priority::Background => self.background.push_back((item, priority)),
193	        }
194	    }
195	
196	    fn is_empty(&self) -> bool {
197	        self.interactive.is_empty() && self.background.is_empty()
198	    }
199	
200	    /// The request the checker answers next.
201	    fn next(&mut self) -> Option<T> {
202	        let (raised, waiting): (VecDeque<_>, VecDeque<_>) = std::mem::take(&mut self.background)
203	            .into_iter()
204	            .partition(|(_, priority)| priority.get() == Priority::Interactive);
205	        self.interactive.extend(raised);
206	        self.background = waiting;
207	        let starving = self.streak >= INTERACTIVE_STREAK;
208	        let (next, streak) = match (self.interactive.pop_front(), self.background.is_empty()) {
209	            (Some(interactive), true) => (Some(interactive), 0),
210	            (Some(interactive), false) if !starving => (Some(interactive), self.streak + 1),
211	            (Some(interactive), false) => {
212	                self.interactive.push_front(interactive);
213	                (self.background.pop_front(), 0)
214	            }
215	            (None, _) => (self.background.pop_front(), 0),
216	        };
217	        self.streak = streak;
218	        next.map(|(item, _)| item)
219	    }
220	}
