222	/// A warm `tsc` that answers for the components it is asked about. Dropping it stops the process.
223	pub struct OnDemand {
224	    jobs: Option<UnboundedSender<Job>>,
225	    thread: Option<JoinHandle<()>>,
226	    /// Receives once when the worker has stopped `tsc` and is about to exit.
227	    stopped: std::sync::Mutex<Option<mpsc::Receiver<()>>>,
228	    shutdown_wait: Duration,
229	    gauges: Arc<Gauges>,
230	}
