232	impl OnDemand {
233	    /// Starts the worker thread. The `tsc` process itself starts on the first request, or on [`OnDemand::warm_up`].
234	    pub fn new(config: OnDemandConfig) -> Self {
235	        let shutdown_wait = config.shutdown_wait;
236	        let (jobs, queue) = unbounded_channel();
237	        let (stopped_tx, stopped) = mpsc::channel();
238	        let gauges = Arc::new(Gauges::default());
239	        let worker_gauges = Arc::clone(&gauges);
240	        let thread = std::thread::Builder::new()
241	            .name("caliper-tsc".to_string())
242	            .spawn(move || {
243	                worker(config, queue, worker_gauges);
244	                stopped_tx.send(()).ok();
245	            })
246	            .ok();
247	        Self {
248	            jobs: thread.as_ref().map(|_| jobs),
249	            thread,
250	            stopped: std::sync::Mutex::new(Some(stopped)),
251	            shutdown_wait,
252	            gauges,
253	        }
254	    }
