256	    /// How many times the process has been replaced so far, by cause. A replacement happens after the reply it
257	    /// follows, so read this after the next request to see the last one.
258	    pub fn recycles(&self) -> Recycles {
259	        Recycles {
260	            worn: self.gauges.worn.load(Ordering::Relaxed),
261	            bloated: self.gauges.bloated.load(Ordering::Relaxed),
262	        }
263	    }
264	
265	    /// How many snapshots the answers so far came from, by how each was made.
266	    pub fn snapshots(&self) -> Snapshots {
267	        Snapshots {
268	            created: self.gauges.created.load(Ordering::Relaxed),
269	            updated: self.gauges.updated.load(Ordering::Relaxed),
270	        }
271	    }
