273	    /// The operating system's id of the `tsc` process that answered the last request, `None` before the first one.
274	    /// Read after a reply, it is the process that built that answer.
275	    pub fn process_id(&self) -> Option<u32> {
276	        Some(self.gauges.process.load(Ordering::Relaxed)).filter(|pid| *pid != 0)
277	    }
