279	    /// Starts `tsc` in the background so the first request does not pay for it.
280	    pub fn warm_up(&self) {
281	        if let Some(jobs) = &self.jobs {
282	            jobs.send(Job::Warm).ok();
283	        }
284	    }
285	}
