289	        let (reply, receiver) = mpsc::sync_channel(1);
290	        let delivery = Delivery::new(move |outcome| {
291	            // `None` drops the sender, which the receiver reads as a checker that stopped without answering.
292	            if let Some(outcome) = outcome {
293	                reply.send(outcome).ok();
294	            }
295	        });
