300	    fn request_at(&self, targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
301	        match &self.jobs {
302	            Some(jobs) => {
303	                if let Err(refused) = jobs.send(Job::Answer(Asked { targets, priority, delivery }))
304	                    && let Job::Answer(asked) = refused.0
305	                {
306	                    asked.delivery.deliver(Some(SemanticOutcome::unavailable("the checker thread has stopped")));
307	                }
308	            }
309	            None => delivery.deliver(Some(SemanticOutcome::unavailable("could not start the checker thread"))),
310	        }
