320	impl Drop for OnDemand {
321	    fn drop(&mut self) {
322	        // Closing the queue ends the worker loop, which shuts `tsc` down before the thread exits. A worker still inside
323	        // a long request is left to finish it: `tsc` stops when it does, or with this process.
324	        self.jobs.take();
325	        let receiver = self.stopped.get_mut().ok().and_then(Option::take);
326	        let stopped = receiver.is_none_or(|receiver| receiver.recv_timeout(self.shutdown_wait).is_ok());
327	        if let Some(thread) = self.thread.take()
328	            && stopped
329	        {
330	            thread.join().ok();
331	        }
332	    }
333	}
