335	fn worker(config: OnDemandConfig, mut queue: UnboundedReceiver<Job>, gauges: Arc<Gauges>) {
336	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
337	        Ok(runtime) => runtime,
338	        Err(error) => {
339	            let reason = format!("could not start an async runtime: {error}");
340	            while let Some(job) = queue.blocking_recv() {
341	                match job {
342	                    Job::Answer(asked) => asked.delivery.deliver(Some(SemanticOutcome::unavailable(reason.clone()))),
343	                    Job::Warm | Job::Changed(_) => {}
344	                }
345	            }
346	            return;
347	        }
348	    };
349	    runtime.block_on(async move {
350	        let mut checker = Checker { gauges, ..Checker::default() };
351	        let mut waiting = Queue::default();
352	        let mut open = true;
353	        loop {
354	            // Every job sent so far is taken before the next request is picked, so the queues hold every request that
355	            // waits, and a change is applied before any request sent after it.
356	            if waiting.is_empty() && open {
357	                match queue.recv().await {
358	                    Some(job) => checker.take(&config, job, &mut waiting).await,
359	                    None => open = false,
360	                }
361	            }
362	            while open {
363	                match queue.try_recv() {
364	                    Ok(job) => checker.take(&config, job, &mut waiting).await,
365	                    Err(TryRecvError::Empty) => break,
366	                    Err(TryRecvError::Disconnected) => open = false,
367	                }
368	            }
369	            let Some(asked) = waiting.next() else {
370	                match open {
371	                    true => continue,
372	                    false => break,
373	                }
374	            };
375	            asked.delivery.deliver(Some(checker.answer(&config, asked.targets).await));
376	            // After the reply, so the caller never waits for the memory check or the replacement.
377	            checker.maintain(&config).await;
378	        }
379	        if let Some(supervisor) = checker.supervisor.take() {
380	            supervisor.shutdown().await.ok();
381	        }
382	    });
383	}
