387	    supervisor: Option<Supervisor>,
388	    /// Compiler options read once from the tsconfig for the running process.
389	    options: Option<serde_json::Value>,
390	    restarts: u32,
391	    /// Requests the running process has answered.
392	    served: u32,
393	    /// Why the checker cannot be used for the rest of the session.
394	    down: Option<String>,
395	    gauges: Arc<Gauges>,
396	    /// The snapshot the last request was answered from, kept for the next.
397	    live: Option<Live>,
398	    /// Files announced as changed since `live` was brought up to date.
399	    told: FxHashSet<Utf8PathBuf>,
400	}
