402	/// A snapshot kept between requests, and what its program read.
403	struct Live {
404	    rpc: Arc<Rpc>,
405	    /// The files its program is rooted at.
406	    roots: Vec<String>,
407	    /// When the files were compared with the disk, just before the snapshot was built or brought up to date.
408	    read_from: SystemTime,
409	    /// Every file the program read, as it was then; `None` until listed after the reply the snapshot built.
410	    stamps: Option<FxHashMap<Utf8PathBuf, Stamp>>,
411	}
