413	/// The warning an answer carries when files the snapshot read changed and the checker was not told.
414	fn untold_warning(files: &[Utf8PathBuf]) -> Diagnostic {
415	    let mut named: Vec<String> = files.iter().take(UNTOLD_NAMED).map(ToString::to_string).collect();
416	    if files.len() > UNTOLD_NAMED {
417	        named.push(format!("{} more", files.len() - UNTOLD_NAMED));
418	    }
419	    Diagnostic::new(
420	        DiagnosticSeverity::Warning,
421	        DiagnosticCode::SemanticBackend,
422	        format!(
423	            "the TypeScript checker was not told that {} changed; it read every file again for this answer",
424	            named.join(", ")
425	        ),
426	    )
427	    .with_help(
428	        "Whatever writes the project's files must tell the session (`update_file` or `ensure_fresh`); an edit the \
429	         checker is not told about is answered from the text it read before.",
430	    )
431	}
432	
433	impl Checker {
434	    /// Acts on a job as it arrives: starts the process, applies a change, or files a request by its priority.
435	    async fn take(&mut self, config: &OnDemandConfig, job: Job, waiting: &mut Queue<Asked>) {
436	        match job {
437	            Job::Warm => {
438	                self.ensure(config).await.ok();
439	            }
440	            Job::Changed(change) => self.told(change).await,
441	            Job::Answer(asked) => {
442	                let priority = asked.priority.clone();
443	                waiting.push(asked, priority);
444	            }
445	        }
446	    }
447	
448	    async fn ensure(&mut self, config: &OnDemandConfig) -> Result<(), String> {
449	        if let Some(reason) = &self.down {
450	            return Err(reason.clone());
451	        }
452	        if self.supervisor.as_ref().is_some_and(|supervisor| !supervisor.is_alive()) {
453	            if let Some(dead) = self.supervisor.take() {
454	                dead.shutdown().await.ok();
455	            }
456	            self.options = None;
457	            self.live = None;
458	            self.told.clear();
459	            self.restarts += 1;
460	            if self.restarts > MAX_RESTARTS {
461	                return Err(self.stay_down("the checker kept crashing".to_string()));
462	            }
463	        }
464	        if self.supervisor.is_none() {
465	            let request = SemanticRequest {
466	                project_root: config.project_root.clone(),
467	                tsconfig: config.tsconfig.clone(),
468	                tsc_path: config.tsc_path.clone(),
469	                targets: Vec::new(),
470	                request_timeout: config.request_timeout,
471	                expected_versions: config.expected_versions,
472	                record_to: None,
473	                extra_env: config.extra_env.clone(),
474	                reverse_queries: false,
475	            };
476	            let started = supervisor_config(&request).map_err(|reason| self.stay_down(reason))?;
477	            let supervisor = match Supervisor::spawn(started).await {
478	                Ok(supervisor) => supervisor,
479	                Err(error) => return Err(self.stay_down(error.to_string())),
480	            };
481	            // Initialize the session and read the compiler options once; every request after builds only its program.
482	            let tsconfig = config.tsconfig.as_ref().map(|path| path.as_str());
483	            match Rpc::prepare(&supervisor.client(), config.request_timeout, tsconfig).await {
484	                Ok(options) => self.options = Some(options),
485	                Err(error) => {
486	                    supervisor.shutdown().await.ok();
487	                    return Err(self.stay_down(format!("the checker did not initialize: {error}")));
488	                }
489	            }
490	            self.supervisor = Some(supervisor);
491	        }
492	        Ok(())
493	    }
494	
495	    fn stay_down(&mut self, reason: String) -> String {
496	        self.down = Some(reason.clone());
497	        reason
498	    }
499	
500	    async fn answer(&mut self, config: &OnDemandConfig, targets: Vec<SemanticTarget>) -> SemanticOutcome {
501	        if let Err(reason) = self.ensure(config).await {
502	            return SemanticOutcome::unavailable(reason);
503	        }
504	        let Some(supervisor) = self.supervisor.as_ref() else {
505	            return SemanticOutcome::unavailable("the checker is not running");
506	        };
507	        let (client, process) = (supervisor.client(), supervisor.process_id());
508	        let mut request = SemanticRequest::new(config.project_root.clone(), targets);
509	        request.tsconfig = config.tsconfig.clone();
510	        request.tsc_path = config.tsc_path.clone();
511	        request.request_timeout = config.request_timeout;
512	        request.expected_versions = config.expected_versions;
513	        request.extra_env.clone_from(&config.extra_env);
514	        let roots = root_files(&request);
515	        if roots.is_empty() {
516	            return group_by_file(&request).0;
517	        }
518	        let answered = match self.snapshot_for(client, config.request_timeout, roots.clone()).await {
519	            Ok((rpc, warning)) => answer_on(&rpc, &request, &roots).await.map(|mut outcome| {
520	                outcome.diagnostics.extend(warning);
521	                outcome
522	            }),
523	            Err(error) => Err(error),
524	        };
525	        self.gauges.process.store(process.unwrap_or(0), Ordering::Relaxed);
526	        self.served += 1;
527	        match answered {
528	            Ok(outcome) => outcome,
529	            Err(error) => {
530	                self.forget().await;
531	                SemanticOutcome::unavailable(format!("the checker stopped answering: {error}"))
532	            }
533	        }
534	    }
535	
536	    /// The snapshot to answer from, its program rooted at `roots`: the kept one brought up to date with the files the
537	    /// checker was told about, or a fresh one when none is kept, the kept one cannot be checked or updated, or a file
538	    /// it read changed with nobody telling the checker. The last comes with a warning that names the files.
539	    async fn snapshot_for(
540	        &mut self,
541	        client: Client,
542	        deadline: Duration,
543	        roots: Vec<String>,
544	    ) -> Result<(Arc<Rpc>, Option<Diagnostic>), CallError> {
545	        let read_from = SystemTime::now();
546	        let told = std::mem::take(&mut self.told);
547	        let mut warning = None;
548	        if let Some(live) = self.live.take() {
549	            if let Some(stamps) = &live.stamps {
550	                let drift = stamps::drift(stamps, &told);
551	                if drift.untold.is_empty() {
552	                    let reread: BTreeSet<Utf8PathBuf> = told.into_iter().chain(drift.unsure).collect();
553	                    if reread.is_empty() && live.roots == roots {
554	                        let rpc = live.rpc.clone();
555	                        self.live = Some(live);
556	                        return Ok((rpc, None));
557	                    }
558	                    let (changed, deleted): (Vec<String>, Vec<String>) = {
559	                        let (present, gone): (Vec<_>, Vec<_>) = reread.into_iter().partition(|file| file.exists());
560	                        (present.into_iter().map(String::from).collect(), gone.into_iter().map(String::from).collect())
561	                    };
562	                    let rerooted = (live.roots != roots).then_some(roots.as_slice());
563	                    match live.rpc.updated(&changed, &deleted, rerooted).await {
564	                        Ok(rpc) => {
565	                            live.rpc.release().await;
566	                            let rpc = Arc::new(rpc);
567	                            self.gauges.updated.fetch_add(1, Ordering::Relaxed);
568	                            self.live = Some(Live { rpc: rpc.clone(), roots, read_from, stamps: None });
569	                            return Ok((rpc, None));
570	                        }
571	                        Err(CallError::Rejected(message)) => {
572	                            tracing::debug!(%message, "the checker could not update its snapshot; building a fresh one");
573	                        }
574	                        Err(fatal) => return Err(fatal),
575	                    }
576	                } else {
577	                    tracing::warn!(files = ?drift.untold, "files changed that the checker was not told about");
578	                    warning = Some(untold_warning(&drift.untold));
579	                }
580	            }
581	            live.rpc.release().await;
582	        }
583	        let options = self.options.as_ref().ok_or_else(|| CallError::Fatal("the checker is not initialized".into()))?;
584	        let rpc = Arc::new(Rpc::open_with(client, deadline, options, &roots, false).await?);
585	        self.gauges.created.fetch_add(1, Ordering::Relaxed);
586	        self.live = Some(Live { rpc: rpc.clone(), roots, read_from, stamps: None });
587	        Ok((rpc, warning))
588	    }
589	
590	    /// Files changed on disk: the kept snapshot reads them again at the next request, or, when anything may have
591	    /// changed, is dropped.
592	    async fn told(&mut self, change: SourceChange) {
593	        match change {
594	            SourceChange::Files(files) if self.live.is_some() => self.told.extend(files),
595	            SourceChange::Files(_) => {}
596	            SourceChange::Everything => self.forget().await,
597	        }
598	    }
599	
600	    /// Drops the kept snapshot, so the next request builds one from the disk.
601	    async fn forget(&mut self) {
602	        self.told.clear();
603	        if let Some(live) = self.live.take() {
604	            live.rpc.release().await;
605	        }
606	    }
607	
608	    /// Lists and stamps the files the kept snapshot's program read, once, after the reply it answered, so the first
609	    /// answer does not wait for it. A snapshot that cannot be listed cannot be checked, and is dropped.
610	    async fn stamp(&mut self) {
611	        let Some(live) = self.live.as_mut().filter(|live| live.stamps.is_none()) else { return };
612	        match live.rpc.source_file_names().await {
613	            Ok(files) => {
614	                live.stamps = Some(stamps::record(files.into_iter().map(Utf8PathBuf::from).collect(), live.read_from))
615	            }
616	            Err(error) => {
617	                tracing::debug!(%error, "could not list the snapshot's files; the next request builds a fresh one");
618	                self.forget().await;
619	            }
620	        }
621	    }
622	
623	    /// Replaces the process when it has built enough programs or grown past the memory bound, and otherwise stamps
624	    /// the snapshot it keeps. A planned replacement, not a crash: the next request starts a fresh process.
625	    async fn maintain(&mut self, config: &OnDemandConfig) {
626	        let Some(supervisor) = self.supervisor.as_ref() else { return };
627	        let worn = self.served >= MAX_REQUESTS_PER_PROCESS;
628	        let resident = (!worn && self.served.is_multiple_of(RSS_CHECK_EVERY))
629	            .then(|| supervisor.process_id().and_then(resident_mib))
630	            .flatten();
631	        let bloated = resident.is_some_and(|mib| mib > config.max_rss_mib);
632	        if worn || bloated {
633	            let (count, cause) = if worn { (&self.gauges.worn, "worn") } else { (&self.gauges.bloated, "bloated") };
634	            count.fetch_add(1, Ordering::Relaxed);
635	            tracing::debug!(cause, served = self.served, resident_mib = ?resident, "replacing the checker process");
636	            // The snapshot goes with the process; the next one reads every file from the disk.
637	            self.live = None;
638	            self.told.clear();
639	            if let Some(old) = self.supervisor.take() {
640	                old.shutdown().await.ok();
641	            }
642	            self.options = None;
643	            self.served = 0;
644	            return;
645	        }
646	        self.stamp().await;
647	    }
648	}
649	
650	#[cfg(test)]
651	mod tests {
652	    use caliper_docgen_core::types::semantic::{Priority, SharedPriority};
653	
654	    use super::{INTERACTIVE_STREAK, Queue, resident_mib};
655	
656	    fn drain(queue: &mut Queue<&'static str>) -> Vec<&'static str> {
657	        std::iter::from_fn(|| queue.next()).collect()
658	    }
659	
660	    fn push(queue: &mut Queue<&'static str>, item: &'static str, priority: Priority) -> SharedPriority {
661	        let priority = SharedPriority::new(priority);
