#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SourceChange {
    /// These files were edited, created or deleted.
    Files(Vec<Utf8PathBuf>),
    /// Anything may have changed: the session extracted everything again (a resolution config changed, or it started).
    Everything,
}

impl SemanticOutcome {
    /// An outcome for a backend that did nothing: the structural result stands, for this reason.
    pub fn unavailable(reason: impl Into<String>) -> Self {
        let diagnostic = Diagnostic::new(
            DiagnosticSeverity::Warning,
            DiagnosticCode::SemanticBackend,
            format!("TypeScript checker backend unavailable: {}", reason.into()),
        )
        .with_help(
            "The structural result is used instead. Install `typescript@beta` (7.1) or `tsrs`, or pass `--tsc-path`.",
        );
        Self { diagnostics: vec![diagnostic], ..Self::default() }
    }
}

/// Replaces `entry`'s props and `composes` with the checker's, keeping what only the structural pass has (a default
/// value, and a description or tags when the checker has none). A prop whose type the checker could not read keeps its
/// structural type, marked (see [`merge_semantic_props`]). `shared` interns identical props across the components of
/// one merge. Returns how many props kept their structural type that way.
pub fn apply_semantic_props(
    entry: &mut ComponentEntry,
    semantic: &SemanticComponent,
    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
/// Resolve the components the structural pass found with TypeScript's checker, all in one program, and merge the answer
/// over `output`. The run waits for the checker; one request (or its start) that takes longer than `timeout`, like an
/// unavailable checker, leaves `output` as it was, plus one diagnostic.
fn apply_semantic_backend(
    options: &caliper_docgen_core::pipeline::PipelineOptions,
    timeout: std::time::Duration,
    output: &mut caliper_docgen_core::types::ExtractionOutput,
) {
    let project_root = options
        .src_dirs
        .first()
        .and_then(|dir| caliper_docgen_core::canonical_path::canonicalize(dir).ok())
        .or_else(|| std::env::current_dir().ok().and_then(|dir| camino::Utf8PathBuf::from_path_buf(dir).ok()));
    let Some(project_root) = project_root else {
        let outcome = caliper_docgen_core::types::semantic::SemanticOutcome::unavailable("no project directory");
        caliper_docgen_core::types::semantic::merge_semantic(output, outcome);
        return;
    };
    let mut request =
        caliper_docgen_semantic::SemanticRequest::new(project_root, caliper_docgen_semantic::targets_of(output));
    request.tsconfig = options
        .tsconfig_path
        .clone()
        .or_else(|| request.project_root.ancestors().map(|dir| dir.join("tsconfig.json")).find(|file| file.is_file()));
    request.tsc_path = options.semantic_tsc_path.clone();
    request.request_timeout = timeout;
    let outcome = caliper_docgen_semantic::resolve(request);
    caliper_docgen_core::types::semantic::merge_semantic(output, outcome);
}

/// `--format rdt`: react-docgen-typescript's shape, shared with the NAPI binding. Like react-docgen-typescript, only
/// exported components unless asked.
pub fn serialize_rdt(
    output: &caliper_docgen_core::types::ExtractionOutput,
    include_unexported: bool,
) -> serde_json::Result<String> {
    /// default), those and project sources of more than 30 props (`'all'`), or none.
    #[napi(ts_type = "'dependencies' | 'all' | 'none'")]
    pub collapse_inherited_props: Option<String>,
    /// Session only (`createSession`, `initializeSession`, `extractFileIncremental`): parse and index every file, and
    /// resolve a component when `sessionDocgenInfo` asks for it (off by default; ADR 0016). `initializeSession` then
    /// returns an output with no components.
    pub lazy: Option<bool>,
    /// Session only: `'on-demand'` asks TypeScript's 7.1 checker for each component a request names, and answers
    /// with the structural props when the checker is slower than `semanticWaitMs` (experimental; ADR 0022). Needs
    /// `typescript@beta` installed or `tscPath`. `'off'` (the default) never starts it.
    #[napi(ts_type = "'off' | 'on-demand'")]
    pub semantic_types: Option<String>,
    /// Session only, with `semanticTypes: 'on-demand'`: the `tsc` binary to run, instead of the nearest
    /// `node_modules/typescript/bin/tsc` or `node_modules/tsrs/bin/tsrs`.
    pub tsc_path: Option<String>,
    /// Session only, with `semanticTypes: 'on-demand'`: how many milliseconds a request waits for the checker before
    /// it takes the structural answer (default 150).
    pub semantic_wait_ms: Option<u32>,
    /// Session only, with `semanticTypes: 'on-demand'`: how many milliseconds a request waits for the checker when the
    /// structural pass lists no props for the component (default 2000). A value below `semanticWaitMs` gives such a
    /// component `semanticWaitMs`.
    pub semantic_wait_empty_ms: Option<u32>,
}

/// How long a request waits for the checker when `semanticWaitMs` is not set: about the first-story budget.
const DEFAULT_SEMANTIC_WAIT_MS: u32 = 150;

/// An empty session for `options`: lazy when they say so, with a checker attached when they ask for one.
fn new_session(options: JsExtractOptions) -> napi::Result<Arc<WatchSession>> {
