pub type SnapshotID = u64;

static SESSION_ID_COUNTER: AtomicU64 = AtomicU64::new(0);

/// Go `StdioServerOptions` / `SessionOptions` subset that affects session behavior.
pub struct SessionOptions {
    pub cwd: String,
    pub default_library_path: String,
    /// Base filesystem (normally `bundled::wrap_fs(osvfs::fs())`, optionally wrapped by the callback FS).
    pub fs: Arc<dyn FS>,
    /// Go `UseBinaryResponses`: true for the sync `MessagePack` protocol, false for JSON-RPC.
    pub binary_responses: bool,
    /// Go `RunExternalCode` (false by default): allows configured content mappers to execute.
    pub run_external_code: bool,
    /// Go `ContentMapperSpawner`: launches content mapper processes (None when the host cannot spawn them).
    pub content_mapper_spawner: Option<Arc<dyn tsrs_contentmapper::Spawner>>,
}

impl SessionOptions {
    pub fn new(
        cwd: String,
        default_library_path: String,
        fs: Arc<dyn FS>,
        binary_responses: bool,
    ) -> SessionOptions {
        SessionOptions {
            cwd,
            default_library_path,
            fs,
            binary_responses,
            run_external_code: false,
            content_mapper_spawner: None,
        }
    }
}

/// Go `snapshotOpenState`: projects/files this client opened in a snapshot lineage.
#[derive(Clone, Default)]
pub struct OpenState {
    pub open_projects: tsrs_core::collections::Set<tsrs_core::tspath::Path>,
    pub open_files: tsrs_core::collections::Set<tsrs_core::tspath::Path>,
    base_fs: Arc<dyn FS>,
    weak_self: std::sync::Weak<Session>,
    pub(crate) build_state: crate::build::BuildState,
    pub(crate) source_files: crate::sourcefiles::SourceFileState,
    build_backend: Mutex<Option<Arc<dyn crate::build::BuildBackend>>>,
    next_batch_page: AtomicU64,
}

impl Session {
    /// Go `NewStandaloneSession`.
    pub fn new(options: SessionOptions) -> Arc<Session> {
        let init = tsrs_project::SessionInit {
            background_ctx: Context::background(),
            options: Arc::new(tsrs_project::SessionOptions {
                current_directory: options.cwd,
                default_library_path: options.default_library_path,
                typings_location: String::new(),
                position_encoding: tsrs_lsproto::PositionEncodingKind::UTF8,
                watch_enabled: false,
                logging_enabled: false,
                telemetry_enabled: false,
                push_diagnostics_enabled: false,
                run_external_code: options.run_external_code,
                debounce_delay: std::time::Duration::ZERO,
                checker_pool_options: tsrs_project::CheckerPoolOptions::default(),
            }),
            fs: options.fs,
            client: None,
            logger: None,
            npm_executor: None,
            spawner: options.content_mapper_spawner,
            content_mapper_logger: None,
            parse_cache: None,
            content_mapped_parse_cache: None,
        };
        let base_fs = Arc::clone(&init.fs);
        Self::new_session(
            tsrs_project::new_snapshot_host(&init),
            None,
            base_fs,
            options.binary_responses,
        )
    }

    /// Go `NewLSPSession`: an API session over the language server's project session. Its snapshots are the
    /// language server's (`getCurrentLanguageServerSnapshot`), and the projects, files and programs it opens
            self.use_case_sensitive_file_names(),
        )
    }

    pub(crate) fn use_case_sensitive_file_names(&self) -> bool {
        self.snapshot_host.fs().use_case_sensitive_file_names()
    }

    /// Releases every registered snapshot (Go `Session.Close`). Idempotent; requests after close fail.
    pub fn close(&self) {
        let mut closed = self.closed.lock().unwrap();
        if *closed {
            return;
        }
        *closed = true;
        self.release_language_server_refs();
        self.source_files.release_all_leases();
        let all: Vec<_> = self.snapshots.write().unwrap().drain().collect();
        drop(all);

        // Go `ownsSnapshotHost`: only a standalone session (no project session) owns its snapshot host.
            "getDeclarationEmit" => {
                self.handle_selected_files_emit(p, tsrs_compiler::EmitOnly::EmitOnlyDts)?
            }
            _ => return Err(ApiError::unsupported(method)),
        };
        json_response(&result)
    }
}

impl Handler for Session {
    fn handle_request(&self, method: &str, params: &[u8]) -> ApiResult<Response> {
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            self.dispatch(method, params)
        })) {
            Ok(result) => result,
            Err(panic) => {
                let message = panic
                    .downcast_ref::<String>()
                    .map(String::as_str)
                    .or_else(|| panic.downcast_ref::<&str>().copied())
                    .unwrap_or("unknown panic");
                // tsrs_module's resolver, like pinned Go's (resolver.go `Unexpected moduleResolution`), panics when a
                // module is resolved with a moduleResolution number that names no kind; Go's server crashes there.
                if let Some(n) = message.strip_prefix("Unexpected moduleResolution: ") {
                    return Err(ApiError::client(format!(
                        "unsupported moduleResolution value {n} (not a ModuleResolutionKind)"
                    )));
                }
                Err(ApiError::internal(format!("panic: {message}")))
            }
        }
    }

    fn handle_notification(&self, _method: &str, _params: &[u8]) -> ApiResult<()> {
        // Go `Session.HandleNotification` ignores all notifications.
        Ok(())
    }
}

/// Runs `f` with a fresh arena region as the allocation target and frees the region afterwards. Only for
/// work whose result is owned data (JSON values) and that stores nothing arena-allocated in longer-lived state.
fn scratch<T>(f: impl FnOnce() -> T) -> T {
    let region = tsrs_core::arena::Region::new(64 << 10);
    let result = {
        let _scope = region.enter();
        f()
    };
    drop(region);
    result
}

// Go tsc/internal/ipc (Handler / Conn) and the error values of tsc/internal/api/proto.go.
//
// This is the transport-neutral boundary between the API session (this crate) and the wire runtime
// (crates/tsrs_api_transport). Params and JSON results are raw JSON bytes in both protocols: the sync
// MessagePack tuple protocol carries JSON payloads in `bin` fields, the async protocol is JSON-RPC.

use std::fmt;

/// Go `ErrInvalidRequest` / `ErrClientError` and friends. `Display` reproduces Go's `err.Error()`
/// text, which is what both protocols put on the wire (`jsonrpc.CodeInternalError` + message).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ErrorKind {
    /// Go `ErrInvalidRequest` ("api: invalid request"): malformed params or unknown method.
    InvalidRequest,
    /// Go `ErrClientError` ("api: client error"): stale/invalid handles, missing files, etc.
    ClientError,
    /// A pinned method that tsrs does not implement yet. Never reported as success.
    Unsupported,
    /// Anything else (encoder failure, callback failure, panic in a handler).
    Internal,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ApiError {
    pub kind: ErrorKind,
    pub(crate) message: String,
}

impl ApiError {
    pub(crate) fn invalid_request(message: impl Into<String>) -> ApiError {
        ApiError { kind: ErrorKind::InvalidRequest, message: message.into() }
    }
    pub(crate) fn client(message: impl Into<String>) -> ApiError {
        ApiError { kind: ErrorKind::ClientError, message: message.into() }
    }
    pub(crate) fn unsupported(method: &str) -> ApiError {
        ApiError {
            kind: ErrorKind::Unsupported,
            message: format!("method {method:?} is not implemented by tsrs (see docs/NODE_API.md)"),
        }
    }
    pub(crate) fn internal(message: impl Into<String>) -> ApiError {
        ApiError { kind: ErrorKind::Internal, message: message.into() }
    }
}

impl fmt::Display for ApiError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.kind {
            ErrorKind::InvalidRequest => write!(f, "api: invalid request: {}", self.message),
            ErrorKind::ClientError => write!(f, "api: client error: {}", self.message),
            ErrorKind::Unsupported => write!(f, "api: unsupported: {}", self.message),
            ErrorKind::Internal => f.write_str(&self.message),
        }
    }
}

impl std::error::Error for ApiError {}

pub type ApiResult<T> = Result<T, ApiError>;

/// A request result. Go returns `any`: either a JSON-marshalable value or `RawBinary`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Response {
    /// Serialized JSON text (`null` for Go `nil`).
    Json(String),
    /// Go `RawBinary`: written as a msgpack `bin` payload. Only produced when the session was created with
    /// `binary_responses` (sync `MessagePack` protocol). An empty vec is Go `RawBinary(nil)`.
    Binary(Vec<u8>),
}

impl Response {
    pub(crate) fn null() -> Response {
        Response::Json("null".to_string())
    }
}

/// Go `ipc.Handler`. Implementations must be `Sync`: the async runtime may dispatch concurrent
/// requests, and filesystem callbacks re-enter the transport while a request is in flight.
pub trait Handler: Send + Sync {
    fn handle_request(&self, method: &str, params: &[u8]) -> ApiResult<Response>;
    /// A request that arrives while the server is blocked in a server->client call on the same connection
    /// (sync `MessagePack` mode: the client re-enters the API from a filesystem / resolver callback).
    /// `depth >= 1`. Nested requests are served like top-level ones (Go does the same); resources that are not
    /// reentrant are acquired with the transport's `lock_for_request`, which fails boundedly instead of
    /// deadlocking when the holder is waiting on the client (`crates/tsrs_api_transport/src/reentrancy.rs`).
    fn handle_nested_request(
        &self,
        method: &str,
        params: &[u8],
        depth: u32,
    ) -> ApiResult<Response> {
        let _ = depth;
        self.handle_request(method, params)
    }
    fn handle_notification(&self, method: &str, params: &[u8]) -> ApiResult<()>;
}

/// Server -> client calls (Go `ipc.Conn.Call`), used for filesystem callbacks and
/// `resolveModuleName` callbacks. `params` / result are JSON text.
// Port of microsoft/TypeScript tsc/internal/api (session, proto, callbackfs, requestfilesystem,
// module_resolution) at the commit pinned in the workspace Cargo.toml. See docs/NODE_API.md for the
// integration contract, lane ownership and the per-method coverage matrix.
//
// Lane ownership (Node API effort):
// - core (this crate, except `checker`): session lifecycle, dispatch, snapshots/programs, config,
//   diagnostics, emit/transpile/build, module resolution, request/callback filesystems.
// - checker: `src/checker.rs` and `src/checker/**` (symbol/type/signature/checker/LS query methods).
// - codec: crates/tsrs_api_codec (AST binary encoder/decoder, node index tables).
// - runtime: crates/tsrs_api_transport (MessagePack tuple protocol, JSON-RPC, sync/async conns).

pub mod adapter;
pub(crate) mod batch;
pub mod build;
pub mod config;
pub mod diagnostics;
pub mod handler;
pub mod methods;
pub mod module_resolution;
pub(crate) mod paramfields;
pub mod predecode;
pub mod printing;
pub(crate) mod program;
pub mod raw_options;
