}

/// The built-in checker reads TypeScript's lib from the files it embeds, named `bundled:///libs/lib.*.d.ts`, where a
/// process reads them from its install. Those are still the lib: an interface it declares keeps its name, an alias it
/// declares (`Partial`) is expanded, and a prop it declares names the lib file as its parent's.
#[test]
fn the_lib_the_built_in_checker_embeds_is_read_as_the_lib() {
    let dir = tempfile::Builder::new().prefix("Lib").tempdir().unwrap();
    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
    std::fs::write(
        root.join("Lib.tsx"),
        "export interface LibProps extends Pick<Event, \"type\"> {\n  when: Date;\n  partial: Partial<{ x: number }>;\n}\n\
         export function Lib(props: LibProps) { return null; }\n",
    )
    .unwrap();
    let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });

    let outcome = resolve(SemanticRequest::new(root, targets_of(&output)));

    assert_eq!((outcome.diagnostics.as_slice(), outcome.fallbacks.as_slice()), (&[][..], &[][..]));
    let SemanticOutcome { components, .. } = outcome;
    let props: Vec<_> = components[0]
        .props
        .iter()
        .map(|prop| (prop.name.as_str(), &prop.prop_type, prop.parent.as_ref().map(|parent| parent.clone())))
        .collect();
    let own = |name: &str| Some(PropParent { name: "LibProps".to_string(), file_name: format!("{name}") });
    let lib_props = own(&format!("{}", components[0].key));
    drop(lib_props);
    assert_eq!(
        props,
        [
            ("when", &PropType::Named { name: "Date".into(), args: vec![] }, None),
            (
                "partial",
                &PropType::Object(vec![ObjectField::new("x", PropType::Number, false, String::new())]),
                None
            ),
            ("type", &PropType::String, None),
        ]
    );
}

