1	//! Finding the checker binary the project installed.
2	
3	use camino::{Utf8Path, Utf8PathBuf};
4	
5	/// The binaries searched for in each `node_modules`, in order of precedence: `typescript@7.1`'s `tsc`, then the `tsrs`
6	/// Node shim. An install that has both keeps using `typescript`, as before `tsrs` was supported; `--tsc-path` picks
7	/// the other.
8	const CANDIDATES: [[&str; 3]; 2] = [["typescript", "bin", "tsc"], ["tsrs", "bin", "tsrs"]];
9	
10	/// `explicit` if given (it must exist), else the binary of the nearest `node_modules` at or above `project_root` that
11	/// holds one: `typescript/bin/tsc`, else `tsrs/bin/tsrs`. The version is checked later, when the process is spawned.
12	pub(crate) fn find_tsc(project_root: &Utf8Path, explicit: Option<&Utf8Path>) -> Result<Utf8PathBuf, String> {
13	    if let Some(path) = explicit {
14	        return if path.is_file() { Ok(path.to_owned()) } else { Err(format!("no tsc binary at {path}")) };
15	    }
16	    project_root
17	        .ancestors()
18	        .flat_map(|dir| {
19	            CANDIDATES.map(|parts| parts.iter().fold(dir.join("node_modules"), |path, part| path.join(part)))
20	        })
21	        .find(|candidate| candidate.is_file())
22	        .ok_or_else(|| {
23	            format!(
24	                "no node_modules/typescript/bin/tsc or node_modules/tsrs/bin/tsrs at or above {project_root}; install \
25	                 `typescript@beta` (7.1) or `tsrs`, or pass --tsc-path"
26	            )
27	        })
28	}
29	
30	#[cfg(test)]
31	mod tests {
32	    use super::*;
33	
34	    #[test]
35	    fn the_nearest_installed_typescript_above_the_project_wins() {
36	        let dir = tempfile::tempdir().unwrap();
37	        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
38	        let bin = root.join("node_modules/typescript/bin");
39	        std::fs::create_dir_all(&bin).unwrap();
40	        std::fs::write(bin.join("tsc"), "").unwrap();
41	        let project = root.join("packages/ui");
42	        std::fs::create_dir_all(&project).unwrap();
43	
44	        assert_eq!(find_tsc(&project, None), Ok(bin.join("tsc")));
45	    }
46	
47	    #[test]
48	    fn the_tsrs_shim_is_found_when_typescript_is_not_installed() {
49	        let dir = tempfile::tempdir().unwrap();
50	        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
51	        let bin = root.join("node_modules/tsrs/bin");
52	        std::fs::create_dir_all(&bin).unwrap();
53	        std::fs::write(bin.join("tsrs"), "").unwrap();
54	
55	        assert_eq!(find_tsc(&root.join("packages/ui"), None), Ok(bin.join("tsrs")));
56	    }
57	
58	    #[test]
59	    fn typescript_wins_over_tsrs_in_the_same_node_modules() {
60	        let dir = tempfile::tempdir().unwrap();
61	        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
62	        for (package, binary) in [("typescript", "tsc"), ("tsrs", "tsrs")] {
63	            let bin = root.join("node_modules").join(package).join("bin");
64	            std::fs::create_dir_all(&bin).unwrap();
65	            std::fs::write(bin.join(binary), "").unwrap();
66	        }
67	
68	        assert_eq!(find_tsc(&root, None), Ok(root.join("node_modules/typescript/bin/tsc")));
69	    }
70	
71	    #[test]
72	    fn the_nearest_node_modules_wins_whichever_checker_it_holds() {
73	        let dir = tempfile::tempdir().unwrap();
74	        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
75	        let far = root.join("node_modules/typescript/bin");
76	        let near = root.join("packages/ui/node_modules/tsrs/bin");
77	        for bin in [&far, &near] {
78	            std::fs::create_dir_all(bin).unwrap();
79	        }
80	        std::fs::write(far.join("tsc"), "").unwrap();
81	        std::fs::write(near.join("tsrs"), "").unwrap();
82	
83	        assert_eq!(find_tsc(&root.join("packages/ui/src"), None), Ok(near.join("tsrs")));
84	    }
85	
86	    #[test]
87	    fn a_project_without_typescript_says_where_it_looked() {
88	        let dir = tempfile::tempdir().unwrap();
89	        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
90	
91	        let error = find_tsc(&root, None).unwrap_err();
92	
93	        assert!(error.contains("no node_modules/typescript/bin/tsc"), "{error}");
94	        assert!(error.contains("node_modules/tsrs/bin/tsrs"), "{error}");
95	    }
96	
97	    #[test]
98	    fn an_explicit_path_that_does_not_exist_is_an_error_not_a_search() {
99	        let dir = tempfile::tempdir().unwrap();
100	        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
101	
102	        assert_eq!(find_tsc(&root, Some(&root.join("nope"))), Err(format!("no tsc binary at {}", root.join("nope"))));
103	    }
104	}

