"""Compares two canonical outputs of the same run, process route against built-in: prop and prop-set ids are content
hashes that include the lib file's path, so each id is resolved to what it names before comparing.
usage: compare.py <process> <built-in>
"""
import json
import sys

PREFIX = ("/Users/gabe/Projects/caliper/.claude/worktrees/agent-a19d74b53c3a1e4f1/node_modules/.pnpm/"
          "@tsrs+darwin-arm64@0.23.0-ts7.1.0-beta/node_modules/@tsrs/darwin-arm64/")


def load(path, normalize):
    text = open(path).read()
    count = text.count(PREFIX) if normalize else text.count("bundled:///libs/")
    if normalize:
        text = text.replace(PREFIX, "bundled:///libs/")
    return json.loads(text), count


def resolver(doc):
    tables = {**doc["props"], **doc["propSets"]}

    def deref(value):
        if isinstance(value, str) and value in tables:
            return deref(tables[value])
        if isinstance(value, list):
            return [deref(item) for item in value]
        if isinstance(value, dict):
            return {key: deref(item) for key, item in value.items()}
        return value

    return deref


def resolved(doc):
    deref = resolver(doc)
    return {key: deref(value) for key, value in doc.items() if key not in ("props", "propSets", "stats")}


process, process_paths = load(sys.argv[1], True)
built_in, built_in_paths = load(sys.argv[2], False)
print("lib path occurrences: process", process_paths, "built-in", built_in_paths)
stats = {k: (process["stats"][k], built_in["stats"][k]) for k in process["stats"] if process["stats"][k] != built_in["stats"][k]}
print("stats that differ:", stats)
a, b = resolved(process), resolved(built_in)
for key in a:
    same = a[key] == b.get(key)
    print(key, "same" if same else "DIFFERS")
    if not same and isinstance(a[key], dict):
        keys = [k for k in a[key] if a[key][k] != b[key].get(k)]
        print("  ", len(keys), keys[:10])
print("identical apart from stats and lib paths:", a == b)
lib_props = [v["name"] for v in built_in["props"].values() if "bundled:///libs/" in json.dumps(v)]
print("props whose parent or declarations name a lib file:", len(lib_props), "of", len(built_in["props"]), sorted(lib_props))
deref = resolver(built_in)
comps = sorted(k for k, v in built_in["components"].items() if "bundled:///libs/" in json.dumps(deref(v)))
print("components with such a prop:", len(comps), comps)

